import { useEffect, useState } from "react";
import {useNavigate} from "react-router-dom";

function AdminIndexPage() {
    const [time, setTime] = useState(new Date());
    const [username] = useState("AdminUser");
    const navigate = useNavigate();
    const [activeView, setActiveView] = useState(null); // null, 'users', or 'studies'
    const [users, setUsers] = useState([]);
    const [selectedUser, setSelectedUser] = useState(null);
    const [roleModalUser, setRoleModalUser] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [studies, setStudies] = useState([]);
    const [filteredUsers, setFilteredUsers] = useState([]); // ✅ boş arrayle başlasın
    const [filteredStudies, setFilteredStudies] = useState(studies);
    const [actions, setActions] = useState([]);
    const [showAddUserModal, setShowAddUserModal] = useState(false);
    const [returningFrom, setReturningFrom] = useState(null);
    const [isReturning, setIsReturning] = useState(false);

    // ========== UPDATED: Changed to match backend UserFilter ==========
    const [filter, setFilter] = useState({
        searchValue: "",  // Single search field for name/username/lastname
        role: "",
    });
    const [appliedFilter, setAppliedFilter] = useState({
        searchValue: "",
        role: "",
    });
    // ==================================================================

    const [studyFilter, setStudyFilter] = useState({
        title: "",
        status: "",
        publishStatus: "REJECTED", // ✅ Default to REJECTED
    });

    useEffect(() => {
        const timer = setInterval(() => setTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    useEffect(() => {
        const fetchUsers = async () => {
            setLoading(true);
            setError(null);
            try {
                const token = localStorage.getItem("token");
                const params = new URLSearchParams();

                // Match backend UserFilter fields exactly
                if (appliedFilter.searchValue && appliedFilter.searchValue.trim()) {
                    params.append("searchValue", appliedFilter.searchValue.trim());
                }
                if (appliedFilter.role && appliedFilter.role.trim()) {
                    params.append("role", appliedFilter.role.trim());
                }

                const queryString = params.toString();
                const fullUrl = `http://localhost:8080/api/admin/user-panel${queryString ? `?${queryString}` : ''}`;

                console.log("Full URL:", fullUrl); // Debug

                const response = await fetch(fullUrl, {
                    method: "GET",
                    headers: {
                        "Authorization": `Bearer ${token}`,
                        "Content-Type": "application/json",
                    },
                });

                if (!response.ok) {
                    throw new Error(`Failed to fetch users: ${response.status}`);
                }

                const data = await response.json();
                setUsers(data);
                setFilteredUsers(data); // 🔥 tabloya da yansısın
            } catch (err) {
                setError(err.message);
                console.error("Error fetching users:", err);
            } finally {
                setLoading(false);
            }
        };

        if (activeView === 'users') {
            fetchUsers();
        }
    }, [appliedFilter, activeView]);
    // ================================================================

    // ========== UPDATED: Send only searchValue and role ==========
    useEffect(() => {
        const fetchStudies = async () => {
            setLoading(true);
            setError(null);
            try {
                const token = localStorage.getItem("token");

                // Build query params
                const params = new URLSearchParams();
                if (studyFilter.title && studyFilter.title.trim()) {
                    params.append("title", studyFilter.title.trim());
                }
                if (studyFilter.status && studyFilter.status.trim()) {
                    params.append("status", studyFilter.status.trim());
                }
                if (studyFilter.publishStatus && studyFilter.publishStatus.trim()) {
                    params.append("publishStatus", studyFilter.publishStatus.trim());
                }

                const queryString = params.toString();
                const fullUrl = `http://localhost:8080/api/admin/study-panel${queryString ? `?${queryString}` : ''}`;

                console.log("Fetching studies with URL:", fullUrl); // Debug

                const response = await fetch(fullUrl, {
                    method: "GET",
                    headers: {
                        "Authorization": `Bearer ${token}`,
                        "Content-Type": "application/json",
                    },
                });

                if (!response.ok) {
                    throw new Error(`Failed to fetch studies: ${response.status}`);
                }

                const data = await response.json();
                setStudies(data);
                setFilteredStudies(data);
            } catch (err) {
                setError(err.message);
                console.error("Error fetching studies:", err);
            } finally {
                setLoading(false);
            }
        };

        if (activeView === 'studies') {
            fetchStudies();
        }
    }, [activeView, studyFilter]);
    // ================================================================

    useEffect(() => {
        const fetchStudies = async () => {
            setLoading(true);
            setError(null);
            try {
                const token = localStorage.getItem("token");
                const response = await fetch("http://localhost:8080/api/admin/study-panel", {
                    method: "GET",
                    headers: {
                        "Authorization": `Bearer ${token}`,
                        "Content-Type": "application/json",
                    },
                });

                if (!response.ok) {
                    throw new Error(`Failed to fetch studies: ${response.status}`);
                }

                const data = await response.json();
                setStudies(data);
                setFilteredStudies(data);
            } catch (err) {
                setError(err.message);
                console.error("Error fetching studies:", err);
            } finally {
                setLoading(false);
            }
        };

        if (activeView === 'studies') {
            fetchStudies();
        }
    }, [activeView]);


    const handleSearch = () => {
        setAppliedFilter({...filter});
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter') {
            handleSearch();
        }
    };
    useEffect(() => {
        const fetchCounts = async () => {
            try {
                const token = localStorage.getItem("token");

                const [userRes, studyRes] = await Promise.all([
                    fetch("http://localhost:8080/api/admin/user-panel", {
                        headers: {
                            Authorization: `Bearer ${token}`,
                            "Content-Type": "application/json",
                        },
                    }),
                    fetch("http://localhost:8080/api/admin/study-panel", {
                        headers: {
                            Authorization: `Bearer ${token}`,
                            "Content-Type": "application/json",
                        },
                    }),
                ]);

                if (!userRes.ok || !studyRes.ok) throw new Error("Failed to fetch counts");

                const usersData = await userRes.json();
                const studiesData = await studyRes.json();

                // sadece sayıları güncelle
                setUsers(usersData);
                setStudies(studiesData);
            } catch (err) {
                console.error("Error fetching dashboard counts:", err);
            }
        };

        fetchCounts();
    }, []); // ✅ sadece ilk renderda çalışsın

    useEffect(() => {
        let result = studies;

        if (studyFilter.title) {
            result = result.filter(study =>
                study.title?.toLowerCase().includes(studyFilter.title.toLowerCase())
            );
        }

        if (studyFilter.status) {
            result = result.filter(study =>
                study.status?.toLowerCase() === studyFilter.status.toLowerCase()
            );
        }

        if (studyFilter.publishStatus) {
            result = result.filter(study =>
                study.publishStatus?.toUpperCase() === studyFilter.publishStatus.toUpperCase()
            );
        }

        setFilteredStudies(result);
    }, [studyFilter, studies]);

    const handleLogout = () => {
        localStorage.removeItem("token");
        localStorage.removeItem("user");
        navigate("/");
    };

    const handleProfile = () => {
        navigate("/profile");
    };

    const handleActionLog = async () => {
        setActiveView("actions");
        try {
            const token = localStorage.getItem("token");
            const response = await fetch("http://localhost:8080/api/admin/action-log", {
                method: "GET",
                headers: {
                    "Authorization": `Bearer ${token}`,
                    "Content-Type": "application/json",
                },
            });

            if (!response.ok) {
                throw new Error("Failed to fetch action logs");
            }

            const data = await response.json();

            // 🔹 En yeni log en üstte görünsün
            const sorted = data.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
            setActions(sorted);
        } catch (err) {
            console.error("Error fetching action logs:", err);
            alert("❌ Could not load action logs.");
        }
    };

    const handleSaveRole = async (user, newRole) => {
        try {
            const token = localStorage.getItem("token");
            const res = await fetch(
                `http://localhost:8080/api/admin/change-role/${user.username}?newRole=${newRole}`,
                {
                    method: "PATCH",
                    headers: {
                        Authorization: `Bearer ${token}`,
                        "Content-Type": "application/json",
                    },
                }
            );

            if (res.ok) {
                alert(`✅ Role updated to ${newRole}`);
                setUsers(prev =>
                    prev.map(u =>
                        u.username === user.username ? { ...u, role: newRole } : u
                    )
                );
                setFilteredUsers(prev =>
                    prev.map(u =>
                        u.username === user.username ? { ...u, role: newRole } : u
                    )
                );
                setRoleModalUser(null);
            } else {
                alert("❌ Failed to change role");
            }
        } catch (err) {
            console.error(err);
            alert("❌ Server error while changing role");
        }
    };

    const formattedTime = time.toLocaleTimeString("en-EN", {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
    });
    const formattedDate = time.toLocaleDateString("en-EN", {
        weekday: "long",
        day: "numeric",
        month: "long",
        year: "numeric",
    });

    const handleViewDetails = async (id) => {
        const token = localStorage.getItem("token");
        try {
            const res = await fetch(`http://localhost:8080/api/admin/study/${id}`, {
                headers: { Authorization: `Bearer ${token}` },
            });
            if (!res.ok) throw new Error("Failed to fetch study details");
            const data = await res.json();
            alert(
                `📘 ${data.title}\nStatus: ${data.status}\nResearcher: ${data.researcher}\nParticipants: ${data.participantCount}`
            );
        } catch (err) {
            console.error(err);
            alert("Failed to load details.");
        }
    };

// 🔹 Study engelleme (Block)
    const handleBlockStudy = async (id) => {
        const reason = prompt("Please enter a reason for blocking:");
        if (!reason) return;
        const token = localStorage.getItem("token");
        try {
            const res = await fetch(`http://localhost:8080/api/admin/study/${id}/block`, {
                method: "PATCH",
                headers: {
                    Authorization: `Bearer ${token}`,
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({ reason }),
            });
            if (!res.ok) throw new Error("Failed to block study");
            alert("✅ Study blocked successfully");
        } catch (err) {
            console.error(err);
            alert("❌ Error blocking study");
        }
    };

// 🔹 Study engelini kaldırma (Unblock)
    const handleUnblockStudy = async (id) => {
        const token = localStorage.getItem("token");
        try {
            const res = await fetch(`http://localhost:8080/api/admin/study/${id}/unblock`, {
                method: "PATCH",
                headers: { Authorization: `Bearer ${token}` },
            });
            if (!res.ok) throw new Error("Failed to unblock study");
            alert("✅ Study unblocked successfully");
        } catch (err) {
            console.error(err);
            alert("❌ Error unblocking study");
        }
    };

    useEffect(() => {
        const styleSheet = document.createElement("style");
        document.head.appendChild(styleSheet);
        styleSheet.textContent = `
            @keyframes float {
                0%, 100% { transform: translateY(0px); }
                50% { transform: translateY(-20px); }
            }
            @keyframes pulse {
                0%, 100% { opacity: 0.5; }
                50% { opacity: 0.8; }
            }
            @keyframes spin {
                0% { transform: rotate(0deg); }
                100% { transform: rotate(360deg); }
            }
            .nav-button:hover {
                transform: translateY(-2px);
                box-shadow: 0 8px 20px rgba(14, 165, 233, 0.4);
            }
            .logout-button:hover {
                transform: translateY(-2px);
                box-shadow: 0 8px 20px rgba(239, 68, 68, 0.4);
            }
            .search-button:hover {
                transform: translateY(-2px);
                box-shadow: 0 8px 20px rgba(16, 185, 129, 0.4);
            }
            input:focus {
                border-color: rgba(59, 130, 246, 0.8) !important;
                box-shadow: 0 0 20px rgba(59, 130, 246, 0.4) !important;
                background: rgba(255, 255, 255, 0.08) !important;
            }
            input:disabled {
                opacity: 0.5;
                cursor: not-allowed;
            }
            select:focus {
                border-color: rgba(59, 130, 246, 0.8) !important;
                box-shadow: 0 0 20px rgba(59, 130, 246, 0.4) !important;
                background: rgba(255, 255, 255, 0.08) !important;
            }
            select:disabled {
                opacity: 0.5;
                cursor: not-allowed;
            }
            select option {
                background: #1a1a2e !important;
                color: #ffffff !important;
                padding: 10px !important;
            }
            select option:hover {
                background: #2a2a3e !important;
            }
            .table-row:hover {
                background: rgba(59, 130, 246, 0.05) !important;
            }
            .split-section {
                transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
            }
            .split-section:hover .section-blur {
                backdrop-filter: blur(5px) !important;
            }
            .back-arrow {
                transition: all 0.3s ease;
            }
            .back-arrow:hover {
                transform: translateY(-50%) translateX(-5px) scale(1.1);
            }

            .split-section:hover {
            transform: scale(1.03);
            z-index: 2;
            }
            .split-section:hover::after {
                content: "";
                position: absolute;
                inset: 0;
                border-radius: 20px;
                border: 2px solid rgba(96, 165, 250, 0.5);
                box-shadow: 0 0 30px rgba(96, 165, 250, 0.4);
                pointer-events: none;
                animation: glow 1.5s ease-in-out infinite alternate;
            }
            @keyframes glow {
                from {
                    box-shadow: 0 0 15px rgba(96, 165, 250, 0.3);
                }
                to {
                    box-shadow: 0 0 30px rgba(59, 130, 246, 0.7);
                }
            }
            .split-section:hover .icon {
                transform: translateY(-5px) scale(1.1);
            }
            /* === VIEW TRANSITION ANIMASYONLARI === */
            .view-transition {
              animation-duration: 0.6s;
              animation-fill-mode: both;


            .slide-fade {
              animation-name: fadeIn;
            }
            @keyframes fadeIn {
              0% { opacity: 0; transform: scale(0.97); }
              100% { opacity: 1; transform: scale(1); }
            }
            /* ==== geri dönüş animasyonları ==== */
            .users-return-anim,
            .fade-in {
  animation: fadeSplit 0.8s ease-in-out forwards;
}

@keyframes fadeSplit {
  0% {
    opacity: 0;
    transform: scale(0.98);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}
/* === Fade-in effect for users/studies view === */
.fade-in-view {
  animation: fadeInView 0.7s ease forwards;
}

@keyframes fadeInView {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}
            /* === END VIEW TRANSITION === */
                transition: transform 0.5s ease;
            `;



        return () => {
            document.head.removeChild(styleSheet);
        };
    }, []);

    return (
        <div style={styles.container}>
            <div style={styles.bgCircle1}></div>
            <div style={styles.bgCircle2}></div>
            <div style={styles.bgCircle3}></div>

            <div style={styles.navbar}>
                <div style={styles.navLeft}>
                    <span style={styles.welcomeText}>Welcome Admin, {username}!</span>
                </div>
                <div style={styles.navRight}>
                    <button
                        className="nav-button"
                        style={styles.actionButton}
                        onClick={handleActionLog}
                    >
                        Action Log
                    </button>
                    <button
                        className="nav-button"
                        style={styles.profileButton}
                        onClick={handleProfile}
                    >
                        Profile
                    </button>
                    <button
                        className="logout-button"
                        style={styles.logoutButton}
                        onClick={handleLogout}
                    >
                        Logout
                    </button>
                </div>
            </div>

            {activeView === null ? (
                <div
                    style={styles.splitContainer}
                    className="split-container fade-in"
                >
                    <div
                        className="split-section split-users"
                        style={styles.splitSection}
                        onClick={() => setActiveView('users')}
                    >
                        <div className="section-blur" style={styles.sectionBlur}>
                            <div style={styles.sectionContent}>
                                <div style={styles.iconContainer}>
                                    <svg style={styles.icon} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                                    </svg>
                                </div>
                                <h2 style={styles.sectionTitle}>User Management</h2>
                                <p style={styles.sectionDescription}>Manage users, roles, and permissions</p>
                                <div style={styles.statsBox}>
                                    <span style={styles.statsNumber}>
                                        {users.length === 0 ? "0" : users.length}
                                    </span>
                                    <span style={styles.statsLabel}>Total Users</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div style={styles.divider}></div>

                    <div
                        className="split-section split-studies"
                        style={styles.splitSection}
                        onClick={() => setActiveView('studies')}
                    >
                        <div className="section-blur" style={styles.sectionBlur}>
                            <div style={styles.sectionContent}>
                                <div style={styles.iconContainer}>
                                    <svg style={styles.icon} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" />
                                    </svg>
                                </div>
                                <h2 style={styles.sectionTitle}>Study Management</h2>
                                <p style={styles.sectionDescription}>Create and manage research studies</p>
                                <div style={styles.statsBox}>
                                    <span style={styles.statsNumber}>
                                        {studies.length === 0 ? "0" : studies.length}
                                    </span>
                                    <span style={styles.statsLabel}>Active Studies</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            ) : (
                <div style={styles.mainContent}>
                    <div
                        className="back-arrow"
                        style={styles.backArrow}
                        onClick={() => {
                            document.querySelectorAll('.view-transition').forEach(el => {
                                el.classList.remove('fade-in-view');
                                el.style.animation = 'none';
                            });
                            setTimeout(() => setActiveView(null), 50); // küçük delay ile anında dönüş, animasyonsuz
                        }}
                    >
                        <svg style={styles.arrowIcon} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                        </svg>
                    </div>
                    <div
                        key={activeView}
                        className={`view-transition ${activeView ? 'fade-in-view' : ''}`}
                    >
                    {activeView === 'users' ? (
                        <UserManagementView
                            users={users}
                            filteredUsers={filteredUsers}
                            filter={filter}
                            setSelectedUser={setSelectedUser}
                            setFilter={setFilter}
                            formattedTime={formattedTime}
                            formattedDate={formattedDate}
                            loading={loading}
                            error={error}
                            handleSearch={handleSearch}
                            handleKeyPress={handleKeyPress}
                            setShowAddUserModal={setShowAddUserModal} // ✅ eklendi
                        />
                    ) : activeView === 'studies' ?(
                        <StudyManagementView
                            studies={studies}
                            filteredStudies={filteredStudies}
                            studyFilter={studyFilter}
                            setStudyFilter={setStudyFilter}
                            formattedTime={formattedTime}
                            formattedDate={formattedDate}
                            handleViewDetails={handleViewDetails}        // ✅ EKLE
                            handleBlockStudy={handleBlockStudy}          // ✅ EKLE
                            handleUnblockStudy={handleUnblockStudy}      // ✅ EKLE
                        />
                    ) : (
                        <ActionLogView
                            actions={actions}
                            formattedTime={formattedTime}
                            formattedDate={formattedDate}
                        />
                    )}
                    </div>
                </div>
            )}

            <footer style={styles.footer}>
                <p style={styles.footerText}>© {new Date().getFullYear()} Artifact Comparator - Admin Panel</p>
            </footer>
            <AddUserModal
                visible={showAddUserModal}
                onClose={() => setShowAddUserModal(false)}
                onUserAdded={() => {
                    setShowAddUserModal(false);
                    setAppliedFilter({ ...filter }); // yeni kullanıcı eklendiğinde liste yenilenir
                }}
            />
            <UserDetailsModal

                user={selectedUser}
                onClose={() => setSelectedUser(null)}
                onRoleChange={(user) => setRoleModalUser(user)}
                onDelete={async (user) => {
                    const confirmed = window.confirm(
                        `⚠️ Are you sure you want to delete ${user.username}'s account?`
                    );
                    if (!confirmed) return;

                    try {
                        const token = localStorage.getItem("token");
                        const res = await fetch(`http://localhost:8080/api/admin/delete-user/${user.username}`, {
                            method: "DELETE",
                            headers: {
                                Authorization: `Bearer ${token}`,
                            },
                        });

                        if (res.ok) {
                            alert("✅ User deleted successfully!");
                            // frontend listesinden de çıkar:
                            setUsers(prev => prev.filter(u => u.id !== user.id));
                            setFilteredUsers(prev => prev.filter(u => u.id !== user.id));
                            setSelectedUser(null);
                        } else {
                            alert("❌ Failed to delete user.");
                        }
                    } catch (err) {
                        console.error(err);
                        alert("❌ Server error while deleting user.");
                    }
                }}
            />
            <ChangeRoleModal
                user={roleModalUser}
                onClose={() => setRoleModalUser(null)}
                onSave={handleSaveRole}
            />
        </div>
    );
}

function UserManagementView({
                                users,
                                filteredUsers,
                                filter,
                                setFilter,
                                formattedTime,
                                formattedDate,
                                loading,
                                error,
                                setSelectedUser,
                                handleSearch,
                                handleKeyPress,
                                setShowAddUserModal,
                            }) {
    return (
        <div style={styles.contentCard}>
            <div style={styles.headerGlow}></div>

            <div style={styles.clockSection}>
