        name: user?.name || "",
        lastname: user?.lastname || "",
        email: user?.email || "",
    });

    if (!user) return null;

    return (
        <div style={styles.modalOverlay}>
            <div style={styles.modalCard}>
                {editing ? (
                    <form
                        onSubmit={async (e) => {
                            e.preventDefault();
                            const token = localStorage.getItem("token");
                            try {
                                const res = await fetch(
                                    `http://localhost:8080/api/admin/update-user/${user.username}`,
                                    {
                                        method: "PATCH",
