function AddUserModal({ visible, onClose, onUserAdded }) {
    const [form, setForm] = useState({
        username: "",
        name: "",
        lastname: "",
        email: "",
        password: "",
        role: "PARTICIPANT",
    });

    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState(null);

    if (!visible) return null;

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setMessage(null);

        try {
            const token = localStorage.getItem("token");
            const res = await fetch("http://localhost:8080/api/admin/create-user", {
                method: "POST",
                headers: {
                    "Authorization": `Bearer ${token}`,
                    "Content-Type": "application/json",
                },
                body: JSON.stringify(form),
            });

            if (res.ok) {
                setMessage({ text: "✅ User created successfully", type: "success" });
                setTimeout(() => {
                    onUserAdded();
                }, 1000);
            } else {
                const errText = await res.text();
                setMessage({ text: `❌ ${errText || "Failed to create user"}`, type: "error" });
            }
        } catch (err) {
            setMessage({ text: "❌ Server error", type: "error" });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div style={styles.modalOverlay}>
            <div style={styles.addUserCard}>
                <h2 style={styles.modalTitle}>Add New User</h2>
                <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                    <input
                        style={styles.filterInput}
                        placeholder="Username"
                        value={form.username}
                        onChange={(e) => setForm({ ...form, username: e.target.value })}
                        required
                    />
                    <input
                        style={styles.filterInput}
                        placeholder="Name"
                        value={form.name}
                        onChange={(e) => setForm({ ...form, name: e.target.value })}
                        required
                    />
                    <input
                        style={styles.filterInput}
                        placeholder="Lastname"
                        value={form.lastname}
                        onChange={(e) => setForm({ ...form, lastname: e.target.value })}
                        required
                    />
                    <input
                        style={styles.filterInput}
                        type="email"
                        placeholder="Email"
                        value={form.email}
                        onChange={(e) => setForm({ ...form, email: e.target.value })}
                        required
                    />
                    <input
                        style={styles.filterInput}
                        type="password"
                        placeholder="Password"
                        value={form.password}
                        onChange={(e) => setForm({ ...form, password: e.target.value })}
                        required
                    />
                    <select
                        style={styles.roleSelect}
                        value={form.role}
                        onChange={(e) => setForm({ ...form, role: e.target.value })}
                    >
                        <option value="ADMIN">Admin</option>
                        <option value="RESEARCHER">Researcher</option>
                        <option value="REVIEWER">Reviewer</option>
                        <option value="PARTICIPANT">Participant</option>
                    </select>

                    <button
                        type="submit"
                        disabled={loading}
                        style={{
                            ...styles.roleButton,
                            background: "linear-gradient(135deg, #10b981, #22c55e)",
                            cursor: loading ? "not-allowed" : "pointer",
                            opacity: loading ? 0.6 : 1,
                        }}
                    >
                        {loading ? "Creating..." : "Create User"}
                    </button>
                    <button type="button" style={styles.closeButton} onClick={onClose}>
                        Cancel
                    </button>
                </form>

                {message && (
                    <div
                        style={{
                            marginTop: "15px",
                            color: message.type === "success" ? "#10b981" : "#ef4444",
                            fontWeight: "600",
                        }}
                    >
                        {message.text}
                    </div>
                )}
            </div>
        </div>
    );
}

